<template><AppShell><section class="form-card"><p class="eyebrow">Account</p><h1>Create an account</h1><form @submit.prevent="submit"><label>First name<input v-model.trim="form.firstName" required /></label><label>Last name<input v-model.trim="form.lastName" required /></label><label>Email<input v-model.trim="form.email" type="email" required /></label><label>Password<input v-model="form.password" type="password" minlength="12" required /></label><label>Account type<select v-model="form.role"><option value="customer">Customer</option><option value="seller">Seller</option></select></label><template v-if="form.role === 'seller'"><label>Business name<input v-model.trim="form.businessName" required /></label><label>Store name<input v-model.trim="form.storeName" required /></label></template><p v-if="message" class="success">{{ message }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button" :disabled="loading">{{ loading ? 'Creating…' : 'Create account' }}</button></form></section></AppShell></template>
<script setup>
import { reactive, ref } from 'vue'; import AppShell from '../../components/common/AppShell.vue'; import { authService } from '../../services/auth.service.js';
const form = reactive({ firstName: '', lastName: '', email: '', password: '', role: 'customer', businessName: '', storeName: '' }); const loading = ref(false); const message = ref(''); const error = ref('');
async function submit() { loading.value = true; error.value = ''; message.value = ''; try { await authService.register(form); message.value = 'Account created. Check your email to verify it before signing in.'; } catch (err) { error.value = err.message; } finally { loading.value = false; } }
</script>
